import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { API } from "../api/api";
import Navbar from "../components/Navbar";

export default function SurveyPage() {
  const { id } = useParams();
  const nav = useNavigate();

  const [survey, setSurvey] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchSurvey();
  }, [id]);
console.log("SURVEY DATA:", survey);
  const fetchSurvey = async () => {
    try {
      const res = await API.get(`/surveys/${id}`);
      setSurvey(res.data);
    } catch (err) {
      console.log("Survey fetch error:", err);
      setSurvey(null);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <p style={{ color: "white" }}>Loading...</p>;
  }

  if (!survey) {
    return (
      <div style={{ color: "white", textAlign: "center", marginTop: 50 }}>
        Survey not found ❌
        <br />
        <button onClick={() => nav("/surveys")}>
          Back
        </button>
      </div>
    );
  }

  return (
    <>
      <Navbar />

      <div style={{
        minHeight: "100vh",
        background: "#0b1220",
        color: "white",
        padding: "30px"
      }}>

        <h2>{survey.title}</h2>
        <p>Category: {survey.category}</p>

        <hr />

        {survey.questions?.map((q, i) => (
          <div
            key={i}
            style={{
              background: "#1f2937",
              padding: 15,
              marginTop: 15,
              borderRadius: 10
            }}
          >
            <h4>{q.questionText}</h4>

            {q.options?.map((opt, j) => (
              <div key={j} style={{
                padding: 8,
                marginTop: 5,
                background: "#374151",
                borderRadius: 6
              }}>
                {opt.text}
              </div>
            ))}
          </div>
        ))}

        <button
          onClick={() => nav("/surveys")}
          style={{
            marginTop: 20,
            padding: 10,
            background: "#3b82f6",
            color: "white",
            border: "none",
            borderRadius: 8
          }}
        >
          ← Back to Surveys
        </button>

      </div>
    </>
  );
}
